    if(cart.filter(l=>l.id===id).reduce((n,l)=>n+l.qty,0)+qty>stock(p)){toast('Ayni paytda '+stock(p)+' dona mavjud.');return false;}
    if(existing)existing.qty+=qty;else cart.push(newLine);
